"""Bounded network-wide interpretation of table-0 rules for concrete ICMP probes.

Unknown matches, actions, controller decisions and ambiguous rules are explicitly
inconclusive. This is a snapshot checker, not a verifier of all possible packets.
"""

import ipaddress
import re

from .topology import host_mac_address


def probe_fields(configuration, source, destination):
    """Describe the untagged IPv4 ICMP echo request generated by the harness."""
    return {
        "dl_src": host_mac_address(source),
        "dl_dst": host_mac_address(destination),
        "dl_type": 0x800,
        "nw_src": configuration.host_ip(source).split("/")[0],
        "nw_dst": configuration.host_ip(destination).split("/")[0],
        "nw_proto": 1,
        "icmp_type": 8,
        "icmp_code": 0,
    }


def parse_flow_dump(text):
    """Keep match fields separate from counters; reject unrecognized dump lines."""
    rules = []
    metadata = {
        "cookie",
        "duration",
        "table",
        "n_packets",
        "n_bytes",
        "idle_age",
        "hard_age",
        "idle_timeout",
        "hard_timeout",
        "priority",
        "importance",
    }
    for line in text.splitlines():
        line = line.strip()
        if not line or re.match(r"^(?:OFPST_FLOW|NXST_FLOW|OFPMP_FLOW) reply\b", line):
            continue
        if "actions=" not in line:
            raise ValueError("Unrecognized flow-dump line: " + line)
        prefix, actions = line.split("actions=", 1)
        values, matches = {}, {}
        for token in prefix.strip().split(","):
            token = token.strip()
            if not token:
                continue
            key, separator, value = token.partition("=")
            (values if key in metadata else matches)[key] = value if separator else None
        rules.append(
            {
                "table": int(values.get("table", "0")),
                "priority": int(values.get("priority", "32768")),
                "matches": matches,
                "actions": actions.strip(),
                "packets": int(values["n_packets"]) if "n_packets" in values else None,
                "raw": line,
            }
        )
    return rules


def rule_matches(rule, packet):
    """Return True, False or None (an unsupported potentially matching field)."""
    unknown = False
    aliases = {
        "eth_src": "dl_src",
        "eth_dst": "dl_dst",
        "eth_type": "dl_type",
        "ip_proto": "nw_proto",
        "ipv4_src": "nw_src",
        "ipv4_dst": "nw_dst",
    }
    protocols = {
        "ip": (0x800, None),
        "icmp": (0x800, 1),
        "tcp": (0x800, 6),
        "udp": (0x800, 17),
        "arp": (0x806, None),
        "ipv6": (0x86DD, None),
    }
    for original_key, value in rule["matches"].items():
        key = aliases.get(original_key, original_key)
        if key in protocols and value is None:
            ethertype, protocol = protocols[key]
            if packet["dl_type"] != ethertype or (
                protocol is not None and packet["nw_proto"] != protocol
            ):
                return False
            continue
        if key not in packet or value is None:
            unknown = True
            continue
        try:
            if key in {"dl_src", "dl_dst"}:
                address, _, mask = value.partition("/")
                number = int(address.replace(":", ""), 16)
                bitmask = int(mask.replace(":", ""), 16) if mask else (1 << 48) - 1
                matched = (
                    int(packet[key].replace(":", ""), 16) & bitmask == number & bitmask
                )
            elif key in {"nw_src", "nw_dst"}:
                matched = ipaddress.ip_address(packet[key]) in ipaddress.ip_network(
                    value, strict=False
                )
            else:
                number, _, mask = value.partition("/")
                bitmask = int(mask, 0) if mask else 0xFFFFFFFF
                matched = int(packet[key]) & bitmask == int(number, 0) & bitmask
        except ValueError:
            unknown = True
            continue
        if not matched:
            return False
    return None if unknown else True


def select_rule(rules, packet):
    """Select the highest-priority definite match unless another rule obscures it."""
    candidates = [
        (rule, rule_matches(rule, packet)) for rule in rules if rule["table"] == 0
    ]
    definite = [rule for rule, matched in candidates if matched is True]
    if not definite:
        return None, (
            "unsupported match" if any(m is None for _, m in candidates) else None
        )
    priority = max(rule["priority"] for rule in definite)
    winners = [rule for rule in definite if rule["priority"] == priority]
    if len(winners) != 1:
        return None, "overlapping rules with equal priority"
    if any(m is None and rule["priority"] >= priority for rule, m in candidates):
        return None, "unsupported match may override selected rule"
    return winners[0], None


def parse_port_dump(text):
    """Read live port availability and flooding flags from dump-ports-desc."""
    ports = {}
    current = None
    for line in text.splitlines():
        match = re.match(r"\s*(\d+)\([^)]*\):", line)
        if match:
            current = int(match[1])
            ports[current] = {}
        elif re.match(r"\s*LOCAL\(", line):
            current = None
        elif current is not None:
            match = re.match(r"\s*(config|state):\s*(.*)", line)
            if match:
                ports[current][match[1]] = match[2].strip()
    return ports


def analyze_forwarding(
    configuration, flow_dumps, source, destination, port_states=None
):
    """Follow every supported output branch; return reachable/unreachable/unknown.

    port_states must describe live ports for output/flood checks. Tests may pass
    explicit zero-flag states for their synthetic topology. No controller table
    or expected policy is consulted when interpreting installed rules.
    """
    links = {switch: {} for switch in configuration.switch_names}
    for host, (switch, port) in configuration.attachments.items():
        links[switch][port] = ("host", host, None)
    for left, left_port, right, right_port in configuration.links:
        links[left][left_port] = ("switch", right, right_port)
        links[right][right_port] = ("switch", left, left_port)
    result = {
        "source": source,
        "destination": destination,
        "reachable": False,
        "delivered_hosts": [],
        "trace": [],
        "unresolved": [],
    }
    try:
        tables = {switch: parse_flow_dump(flow_dumps[switch]) for switch in links}
    except (ValueError, KeyError) as error:
        result["unresolved"].append(str(error))
        result["verdict"] = "INCONCLUSIVE"
        return result
    fields = probe_fields(configuration, source, destination)
    result["packet_fields"] = fields
    pending = [(configuration.attachments[source], [])]
    examined = set()
    while pending:
        (switch, ingress), ancestry = pending.pop()
        if (switch, ingress) in ancestry:
            result["unresolved"].append("Forwarding loop at %s:%d" % (switch, ingress))
            continue
        ingress_state = (port_states or {}).get(switch, {}).get(ingress, {})
        if not {"config", "state"} <= ingress_state.keys():
            result["unresolved"].append(
                "Missing ingress state for %s:%d" % (switch, ingress)
            )
            continue
        if (switch, ingress) in examined:
            continue  # Identical concrete packet state has identical decisions.
        examined.add((switch, ingress))
        ingress_flags = ingress_state["config"] + " " + ingress_state["state"]
        if any(flag in ingress_flags for flag in ("PORT_DOWN", "LINK_DOWN", "NO_RECV")):
            continue
        rule, uncertainty = select_rule(tables[switch], dict(fields, in_port=ingress))
        step = {
            "switch": switch,
            "in_port": ingress,
            "rule": rule,
            "path": ancestry + [(switch, ingress)],
        }
        result["trace"].append(step)
        if uncertainty:
            result["unresolved"].append(switch + ": " + uncertainty)
            continue
        if rule is None or rule["actions"].lower() in {"", "drop"}:
            step["decision"] = "drop"
            continue
        actions = rule["actions"].split(",")
        supported = all(
            re.fullmatch(r"(?:output:)?(?:\d+|IN_PORT|FLOOD|ALL)", a.strip(), re.I)
            for a in actions
        )
        if not supported:
            step["decision"] = "unsupported_or_controller"
            result["unresolved"].append(switch + ": " + rule["actions"])
            continue
        step["decision"] = "output"
        for action in actions:
            port_name = action.strip().upper()
            if port_name.startswith("OUTPUT:"):
                port_name = port_name[len("OUTPUT:") :]
            ports = (
                sorted(set(links[switch]) | set((port_states or {}).get(switch, {})))
                if port_name in {"FLOOD", "ALL"}
                else [ingress if port_name == "IN_PORT" else int(port_name)]
            )
            for port in ports:
                if port == ingress and port_name != "IN_PORT":
                    continue
                state = (port_states or {}).get(switch, {}).get(port, {})
                if not {"config", "state"} <= state.keys():
                    result["unresolved"].append(
                        "Missing live port state for %s:%d" % (switch, port)
                    )
                    continue
                flags = state["config"] + " " + state["state"]
                if "BLOCKED" in flags:
                    result["unresolved"].append(
                        "Unsupported STP state at %s:%d" % (switch, port)
                    )
                    continue
                if any(flag in flags for flag in ("PORT_DOWN", "LINK_DOWN", "NO_FWD")):
                    continue
                if port_name == "FLOOD" and "NO_FLOOD" in flags:
                    continue
                endpoint = links[switch].get(port)
                if endpoint is None:
                    result["unresolved"].append(
                        "Unmapped output %s:%d" % (switch, port)
                    )
                    continue
                kind, target, incoming = endpoint
                if kind == "host":
                    if target not in result["delivered_hosts"]:
                        result["delivered_hosts"].append(target)
                else:
                    peer_state = (port_states or {}).get(target, {}).get(incoming, {})
                    if not {"config", "state"} <= peer_state.keys():
                        result["unresolved"].append(
                            "Missing ingress state for %s:%d" % (target, incoming)
                        )
                    elif not any(
                        flag in peer_state["config"] + " " + peer_state["state"]
                        for flag in ("PORT_DOWN", "LINK_DOWN", "NO_RECV")
                    ):
                        pending.append(((target, incoming), step["path"]))
    result["reachable"] = destination in result["delivered_hosts"]
    result["verdict"] = (
        "INCONCLUSIVE"
        if result["unresolved"]
        else ("REACHABLE" if result["reachable"] else "UNREACHABLE")
    )
    return result
